124: impl RunRecord {
125:     pub fn to_bytes(&self) -> Result<Vec<u8>, String> {
126:         serde_json::to_vec_pretty(self).map_err(|e| e.to_string())
127:     }
128: }
129: 
130: /// Write `run.json` (atomic replace).
131: pub fn write_record(dir: &Path, rec: &RunRecord) -> Result<(), String> {
132:     let bytes = rec.to_bytes()?;
133:     c3_core::store::write_text_atomic(&dir.join("run.json"), &bytes).map_err(|e| e.to_string())
134: }
135: 
136: /// Read one `run.json`. (0.2.4, F91-2) FAIL CLOSED: only a confirmed `NotFound` is absence
137: /// (`Ok(None)`); any other read error, or a parse failure, is `Err` (the message names the
138: /// directory, never the contents) so admission refuses rather than treats an unreadable record as
139: /// an absent run.
140: pub fn read_record(dir: &Path) -> Result<Option<RunRecord>, String> {
141:     let p = dir.join("run.json");
142:     let bytes = match std::fs::read(&p) {
143:         Ok(b) => b,
144:         Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
145:         Err(e) => return Err(format!("{} could not be read ({e})", p.display())),
146:     };
147:     let mut rec: RunRecord = serde_json::from_slice(&bytes)
148:         .map_err(|e| format!("{} does not parse: {e}", p.display()))?;
149:     // A pending record (`running`, or `waiting_quota` while a detached alarm sleeps) whose
150:     // background is gone (the pid is dead, or it never reported one within the start grace) is a
151:     // run that DIED: say so on disk, so `--status`, `--wait` and the one-live-run guard never wait
152:     // on a ghost.
153:     if is_pending(&rec.status) && !is_live(&rec) {
154:         rec.status = "died".into();
155:         rec.ended = Some(chrono::Utc::now().to_rfc3339());
156:         rec.args = None;
157:         let _ = write_record(dir, &rec);
158:     }
159:     Ok(Some(rec))
160: }
161: 
162: /// How long a pending record may go without a reported pid before it counts as dead
163: /// (the background reports its pid within its first second).
164: const START_GRACE_SEC: i64 = 120;
165: 
166: /// Whether a status means the run's background is still supposed to be alive: `running`, or
167: /// `waiting_quota` while a detached run's alarm sleeps until the quota window resets.
168: pub fn is_pending(status: &str) -> bool {
169:     status == "running" || status == "waiting_quota"
170: }
171: 
172: /// Whether a pending record's background is alive: its reported pid exists, or no pid was
173: /// reported yet and the record is younger than [`START_GRACE_SEC`]. Anything else is dead.
174: pub fn is_live(rec: &RunRecord) -> bool {
175:     if !is_pending(&rec.status) {
176:         return false;
177:     }
178:     match rec.pid {
179:         Some(pid) if pid > 0 => crate::liveness::proc::pid_alive(pid as u32, &rec.pid_start),
180:         _ => match chrono::DateTime::parse_from_rfc3339(&rec.started) {
181:             Ok(t) => {
182:                 (chrono::Utc::now() - t.with_timezone(&chrono::Utc)).num_seconds() < START_GRACE_SEC
183:             }
184:             Err(_) => false,
185:         },
186:     }
187: }
