189: /// Every work run directory of a task's `work/` root, by sequence. (0.2.4, F91-2) FAIL CLOSED: a
190: /// missing work root is `Ok([])`, but an enumeration or entry error is `Err`; a directory with the
191: /// `NN-` prefix is a candidate when its `run.json` path EXISTS in any form (file, directory or
192: /// otherwise), so an unreadable or replaced record is NOT silently dropped â€” `read_record` then
193: /// reports the inspection error.
194: pub fn run_dirs(work_root: &Path) -> Result<Vec<(i64, PathBuf)>, String> {
195:     let mut out: Vec<(i64, PathBuf)> = Vec::new();
196:     let rd = match std::fs::read_dir(work_root) {
197:         Ok(rd) => rd,
198:         Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(out),
199:         Err(e) => {
200:             return Err(format!(
201:                 "could not enumerate the work directory {} ({e})",
202:                 work_root.display()
203:             ))
204:         }
205:     };
206:     for entry in rd {
207:         let entry = entry.map_err(|e| {
208:             format!(
209:                 "could not read an entry of the work directory {} ({e})",
210:                 work_root.display()
211:             )
212:         })?;
213:         let name = entry.file_name().to_string_lossy().to_string();
214:         let first = name.split('-').next().unwrap_or("");
215:         if first.is_empty() || !first.chars().all(|c| c.is_ascii_digit()) {
216:             continue;
217:         }
218:         let seq: i64 = first.parse().unwrap_or(0);
219:         if seq <= 0 {
220:             continue;
221:         }
222:         let run_json = entry.path().join("run.json");
223:         match run_json.try_exists() {
224:             Ok(true) => out.push((seq, entry.path())),
225:             Ok(false) => continue, // a directory with no run.json is not a run
226:             Err(e) => {
227:                 return Err(format!(
228:                     "could not inspect {} ({e})",
229:                     run_json.display()
230:                 ))
231:             }
232:         }
233:     }
234:     out.sort_by_key(|(seq, _)| *seq);
235:     Ok(out)
236: }
