238: /// Whether a live work run exists for the task (a `running` or `waiting_quota` record): its id,
239: /// or `None`. (0.2.4, F91-2) `Err` when any candidate record cannot be inspected.
240: pub fn live_run(work_root: &Path) -> Result<Option<String>, String> {
241:     for (_, dir) in run_dirs(work_root)? {
242:         if let Some(r) = read_record(&dir)? {
243:             if is_pending(&r.status) {
244:                 return Ok(Some(r.id));
245:             }
246:         }
247:     }
248:     Ok(None)
249: }
