255:     for (_, dir) in run_dirs(work_root)? {
256:         if dir == exclude {
257:             continue;
258:         }
259:         if let Some(r) = read_record(&dir)? {
260:             if is_pending(&r.status) && is_live(&r) {
261:                 return Ok(Some(r.id));
262:             }
263:         }
264:     }
265:     Ok(None)
