1550: fn do_resume_foreground(o: &Options, rec_dir: &Path, rec: &RunRecord) -> i32 {
1551:     if rec.status != "quota" && rec.status != "timeout" {
1552:         return refuse(&format!(
1553:             "work run {} is in state {}, not quota or timeout; nothing to resume.",
1554:             rec.id, rec.status
1555:         ));
1556:     }
1557:     if rec.quota.as_ref().map(|q| q.exhausted).unwrap_or(false) {
1558:         return refuse(&format!(
1559:             "work run {} has spent its resume cap ({}); it needs a human.",
1560:             rec.id,
1561:             eff_max_resumes_rec(o, rec)
1562:         ));
1563:     }
1564:     let renv = match resume_env(o, rec, rec_dir) {
